export const CURRENCIES=['USD','EUR','GBP','JPY','CHF','AUD','NZD','CAD'];
export const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const sign=v=>v>0?`+${v}`:String(v);const color=s=>s>=60?'positive':s<40?'negative':'neutral';
export const fmt=(v,options={})=>v?new Intl.DateTimeFormat('en-GB',{timeZone:'Europe/Vienna',day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit',...options}).format(new Date(v)):'Not available';
const safeLink=(url,label)=>{try{const u=new URL(url);return u.protocol==='https:'?`<a href="${esc(u.href)}" target="_blank" rel="noopener noreferrer">${esc(label)}</a>`:esc(label)}catch{return esc(label)}};
function metric(label,value,note,primary=false){return `<div class="metric ${primary?'primary':''}"><div class="eyebrow">${esc(label)}</div><strong>${value}</strong><small>${esc(note)}</small></div>`}
function head(title,note='',action=''){return `<div class="panel-head"><div><h2>${esc(title)}</h2>${note?`<p>${esc(note)}</p>`:''}</div>${action}</div>`}
function table(headers,rows,cls=''){return `<div class="table-wrap"><table class="${cls}"><thead><tr>${headers.map(h=>`<th scope="col">${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(v=>`<td>${v}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}
function handoff(p){return !p||p.direction==='UNRATED'?'Unrated — insufficient verified evidence':p.direction==='NEUTRAL'?'Neutral — wait for clearer fundamental separation':`Only look for ${p.direction} setups`}
export function overview({report,index}){
 const ranked=report.currencies,usd=ranked.find(x=>x.currency==='USD'),gbp=ranked.find(x=>x.currency==='GBP'),gap=gbp.score-usd.score,focus=report.focus;const rated=ranked.filter(c=>!c.provisional).length,coverage=report.demo?'Preview':ranked.every(c=>c.quality==='High')?'High':ranked.some(c=>c.quality==='Low')?'Mixed':'Medium';const prev=index.find(r=>r.generatedAt<report.generatedAt);
 return `<div class="metrics">${metric('STRONGEST CURRENCY',`${ranked[0].currency} <span>${ranked[0].score}/100</span>`,ranked[0].bias+(ranked[0].provisional?' · provisional':''),true)}${metric('WEAKEST CURRENCY',`${ranked.at(-1).currency} <span>${ranked.at(-1).score}/100</span>`,ranked.at(-1).bias+(ranked.at(-1).provisional?' · provisional':''))}${metric('LARGEST SEPARATION',`${ranked[0].score-ranked.at(-1).score} <span>points</span>`,`${ranked[0].currency} / ${ranked.at(-1).currency}`)}${metric('EVIDENCE QUALITY',coverage,report.demo?'Synthetic data · not a live assessment':`${rated}/8 currencies eligible for directional analysis`)}</div>
 <div class="overview-grid"><div><section class="panel">${head('Currency strength','Fundamental bias · 0–100','<button class="text-button" data-view="evidence">View evidence ↗</button>')}${ranked.map(c=>`<button class="strength-row" data-currency="${c.currency}" aria-label="${c.currency}, score ${c.score}, view breakdown"><span class="currency">${c.currency}</span><span class="track"><span class="fill ${color(c.score)==='positive'?'':color(c.score)}" style="width:${c.score}%;display:block"></span></span><span class="score">${c.score}${c.provisional?'*':''}</span></button>`).join('')}<div class="scale"><span>Bearish</span><span>50 · Neutral</span><span>Bullish</span></div><div class="ranking">${ranked.map(c=>`${c.rank}. ${c.currency}`).join(' &nbsp; / &nbsp; ')}<br>Tap a currency to inspect its score. Equal scores share a rank.${ranked.some(c=>c.provisional)?'<br>* Provisional: limited evidence.':''}</div></section>
 <section class="panel">${head('Relative-value watchlist','Largest unique pair differences')}${table(['Pair','Bias','Gap','Edge class'],report.pairs.slice(0,6).map(p=>[`<b>${esc(p.pair)}</b>`,`<span class="badge ${p.direction==='SHORT'?'negative':p.direction==='LONG'?'':'neutral'}">${p.direction}</span>`,p.edge,esc(p.edgeClass)]))}<details class="small"><summary>All 28 unique pairs</summary>${table(['Pair','Bias','Gap'],report.pairs.map(p=>[esc(p.pair),esc(p.direction),p.edge]))}</details><p class="small muted">Shared currencies can create overlapping exposure. Edge classes are model labels, not proven trading advantages.</p></section>
 ${!report.demo&&prev?`<section class="panel">${head('Since the previous brief',fmt(prev.generatedAt))}<div class="changes">${ranked.map(c=>`<div><b>${c.currency}</b><span>${sign(c.score-prev.scores[c.currency])}</span></div>`).join('')}</div></section>`:''}</div>
 <div><section class="panel">${head('Your focus','GBP / USD')}<div class="pair-focus">GBPUSD <span class="badge ${gap< -10?'negative':'neutral'}">${focus.direction==='UNRATED'?'Unrated':focus.direction==='NEUTRAL'?'Neutral':gap>0?'Bullish':'Bearish'}</span></div><div class="pair-compare"><div class="pair-number">GBP<strong>${gbp.score}</strong></div><span class="muted">vs</span><div class="pair-number">USD<strong>${usd.score}</strong></div></div><p class="handoff">${handoff(focus)}</p><p class="handoff-note">GBP minus USD: ${sign(gap)} points. ${focus.direction==='UNRATED'?'Evidence quality is insufficient for a directional handoff.':'Wait for a liquidity sweep, MSS/CISD, a fair value gap, and an entry trigger.'}</p></section>
 <section class="panel">${head('The brief','Five things to take into the session')}<ul class="summary">${report.summary.map(s=>`<li>${esc(s)}</li>`).join('')}</ul></section>
 <section class="panel">${head('Pair separation','Row currency minus column currency')}<div class="heatmap" aria-label="Currency score differences"><span></span>${CURRENCIES.map(c=>`<span class="heat-head">${c}</span>`).join('')}${CURRENCIES.map(a=>`<span class="heat-head">${a}</span>${CURRENCIES.map(b=>{const ca=ranked.find(c=>c.currency===a),cb=ranked.find(c=>c.currency===b),n=ca.score-cb.score;return `<div class="heat-cell ${a===b?'muted':n>10?'pos':n< -10?'neg':''}" title="${a} minus ${b}: ${n} points${ca.provisional||cb.provisional?'; provisional':''}">${a===b?'—':sign(n)}</div>`}).join('')}`).join('')}</div><p class="small muted">Positive favors the row currency. Scores are not probabilities.</p></section></div></div>`;
}
function filter(currencyFilter){return `<div class="filter-row"><label for="currency-filter" class="small">Currency</label><select id="currency-filter"><option value="all">All currencies</option>${CURRENCIES.map(c=>`<option ${currencyFilter===c?'selected':''}>${c}</option>`).join('')}</select></div>`}
export function evidence({report,method,currencyFilter}){const rows=(report.evidence||[]).filter(e=>currencyFilter==='all'||e.currency===currencyFilter);return `<section class="panel">${head('Data verification','Release dates, comparisons, and the source behind each factor.')}${filter(currencyFilter)}${report.demo?'':`<p><a class="text-button" href="data/reports/${esc(report.id)}.md" download>Download full seven-section report ↗</a></p>`}${rows.length?table(['Factor / currency','Reading','Source / release date','Consensus / prior','Notes'],rows.map(e=>[`<b>${esc(method.labels?.[e.factor]||e.factor)}</b><small>${e.currency}</small>`,`${esc(e.status==='verified'?e.reading:'Unavailable')}<small>${esc(e.referencePeriod)}</small>`,`${safeLink(e.sourceUrl,e.sourceName||'Source unavailable')}<small>${esc(e.sourceDate||'Date unavailable')}${e.carriedForward?' · retained observation':''}</small>`,`${esc(e.consensus??'Unavailable')} / ${esc(e.prior??'Unavailable')}<small>${e.consensusSourceUrl?safeLink(e.consensusSourceUrl,'Consensus source'):''}</small>`,esc(e.notes)]),'evidence-table'):'<div class="empty">The preview has no claimed economic readings.<br>Live reports will show all 72 factor checks, with dated sources and comparison values.</div>'}</section>${sourceRegistry(method)}`}
function sourceRegistry(method){return `<section class="panel">${head('Research sources','Official releases first. Calendar providers fill timing and consensus gaps.')}<div class="source-list">${Object.entries(method.sources||{}).map(([c,s])=>`<div class="source-item"><b>${c} <span class="muted">/ ${esc(s.name)}</span></b><br>${[s.bank,...s.stats,s.pmi].map(([name,url])=>safeLink(url,name)).join(' ')}</div>`).join('')}</div><p class="small muted">Calendar and consensus: ${safeLink('https://tradingeconomics.com/calendar','Trading Economics')}, ${safeLink('https://www.forexfactory.com/calendar','Forex Factory')}, ${safeLink('https://www.investing.com/economic-calendar/','Investing.com')}. Missing estimates remain unavailable.</p></section>`}
export function calendar({report,currencyFilter}){const events=(report.events||[]).filter(e=>currencyFilter==='all'||e.currency===currencyFilter).sort((a,b)=>(a.instant||a.date).localeCompare(b.instant||b.date));return `<section class="panel">${head('Next seven calendar days','Times shown in Austria local time when an exact event time is verified.')}${filter(currencyFilter)}${events.length?events.map(e=>`<div class="event"><div class="event-time">${e.instant?new Intl.DateTimeFormat('en-GB',{timeZone:'Europe/Vienna',hour:'2-digit',minute:'2-digit'}).format(new Date(e.instant)):'TBA'}<small>${esc(e.instant?new Intl.DateTimeFormat('en-GB',{timeZone:'Europe/Vienna',day:'2-digit',month:'short'}).format(new Date(e.instant)):e.date)}</small></div><div><h3><span class="badge neutral">${e.currency}</span> ${esc(e.event)}</h3><p>${esc(e.relevance)} ${e.consensus?'Consensus: '+esc(e.consensus)+'. ':''}${safeLink(e.sourceUrl,'Source ↗')}</p></div></div>`).join(''):`<div class="empty">${report.demo?'The preview contains no invented event schedule.':'No upcoming events have been verified for this selection.'}<br>Check calendar coverage below before interpreting an empty list.</div>`}</section><section class="panel">${head('Calendar coverage','“None verified” and “unavailable” are different outcomes.')}${report.calendarChecks?.length?table(['Currency','Category','Result','Notes'],report.calendarChecks.filter(c=>currencyFilter==='all'||c.currency===currencyFilter).map(c=>[c.currency,esc(c.category),esc(c.status.replaceAll('_',' ')),`${esc(c.note)} ${c.sourceUrl?safeLink(c.sourceUrl,'Source'):''}`])):'<p class="small muted">Awaiting the first live calendar search.</p>'}</section>`}
export function history({index}){const rows=[...index].reverse(),palette=['#d4ef81','#abc3f1','#e9a79a','#e8d1a1','#8fceb8','#bcaaec','#e6bada','#7dc2d7'];let chart='<div class="empty">History starts with the first published report.<br>No simulated track record is shown.</div>';if(rows.length>=2){const recent=rows.slice(-30),w=760,h=250,x=i=>40+i*(w-65)/(recent.length-1),y=s=>15+(100-s)*(h-50)/100;chart=`<svg class="history-chart" viewBox="0 0 ${w} ${h}" role="img" aria-label="Currency fundamental scores over the last ${recent.length} reports">${[0,25,50,75,100].map(n=>`<line x1="35" y1="${y(n)}" x2="745" y2="${y(n)}" stroke="#344037" ${n===50?'stroke-dasharray="4 4"':''}/><text x="0" y="${y(n)+4}">${n}</text>`).join('')}${CURRENCIES.map((c,ci)=>`<polyline fill="none" stroke="${palette[ci]}" stroke-width="2.2" points="${recent.map((r,i)=>`${x(i)},${y(r.scores[c])}`).join(' ')}"/>`).join('')}<text x="40" y="240">${esc(recent[0].id.slice(0,10))}</text><text x="645" y="240">${esc(recent.at(-1).id.slice(0,10))}</text></svg><div class="chart-legend">${CURRENCIES.map((c,i)=>`<span><i class="legend-swatch" style="background:${palette[i]}"></i>${c}</span>`).join('')}</div>`}else if(rows.length===1)chart='<div class="empty">One report recorded. The trend chart appears after the next report.</div>';return `<section class="panel">${head('Strength over time','Published scores only. This is research history, not investment performance.')}${chart}</section><section class="panel">${head('Report archive',`${index.length} published reports`)}${index.length?table(['Report','Published in Austria','Evidence','Open'],index.map(r=>[esc(r.id),esc(fmt(r.generatedAt)),esc(r.status),`<button class="text-button" data-report="${esc(r.id)}">Read report ↗</button>`])):'<div class="empty">The archive will fill automatically when live research is active.</div>'}</section>`}
export function methodology({method}){return `<section class="panel">${head('How the score works',`Research model ${method.version||'1.0.0'} · transparent, versioned rules`)}<div class="method-copy"><p>Each currency starts at <b>50</b>. Eligible evidence adds or deducts points, with the result bounded between 0 and 100. The score expresses a fundamental bias. It is not a success probability, price forecast, or calibrated trading signal.</p><p><b>Missing evidence is not neutral evidence.</b> Missing, stale, or incomparable observations receive no adjustment and reduce evidence quality. A currency with low evidence quality is provisional; its pairs receive no directional handoff.</p></div>${table(['Component','Rule'],[['Central bank','Strong / moderate hawkish: +15 / +10; neutral or mixed: 0; moderate / strong dovish: −10 / −15. Rate decision is context, not a second adjustment.'],['Inflation','Headline 40%, core 60%; component surprise scores combined and rounded to nearest 5. Opposing surprises: 0. If only one has consensus, use it once and lower coverage.'],['Employment','Strong beat +10; small beat +5; in line 0; miss −10. Exact series and units are fixed for each country.'],['Unemployment','Falling by at least 0.05 percentage points: +5; rising: −5; unchanged: 0. Compare the same series with its prior.'],['GDP','Strong beat +10; beat +5; in line 0; miss −5; large miss −10. Annualized and nonannualized rates never mix.'],['PMI','Below 45: −10; 45 to below 50: −5; 50 through 55: +3; above 55: +5. One configured series; latest final replaces flash.'],['Retail / spending','Above comparable consensus: +5; below: −5; differences below 0.05 pp: 0. Australia uses household spending.'],['Risk','Risk-on: S&P 500 daily change ≥+0.5% and VIX ≤−5%, adding +5 to AUD/NZD. Risk-off: equities ≤−0.5% and VIX ≥+5%, adding +5 to USD/CHF/JPY. Same session, ≤36 hours old. Otherwise mixed, 0.']])}<p class="method-copy"><b>Pair gap:</b> absolute score difference. 0–10 No Edge; 11–20 Weak Edge; 21–40 Tradable Edge; 41–60 Strong Edge; 61+ Exceptional Edge. These requested labels do not establish profitability. Conventional pair notation determines LONG or SHORT. Ties share a rank. A directional edge needs more than 10 points and adequate evidence in both currencies.</p></section><section class="panel">${head('Surprise thresholds','Version 1 heuristics. Percentage-point differences unless employment is in thousands.')}${table(['Currency','CPI small / large','Employment small / large','GDP small / large'],CURRENCIES.map(c=>[c,esc(method.thresholds?.[c]?.cpi.join(' / ')||''),esc(method.thresholds?.[c]?.employment.join(' / ')||''),esc(method.thresholds?.[c]?.gdp.join(' / ')||'')]))}<p class="method-copy">High evidence quality requires 8/9 current observations and 7/8 eligible scoring components; Medium requires 6/9 and 4/8. Otherwise Low. This measures research coverage, not the chance of a winning trade. Headline and core consensus are both required for full inflation coverage.</p><p class="method-copy">Freshness limits: 50 days for monthly releases and PMI; 120 days for GDP, central-bank guidance and decisions, New Zealand quarterly data, and euro-area / Swiss quarterly employment. Older verified readings remain visible but do not affect scores.</p><p class="method-copy">Morning target: 08:30 Austria time. Afternoon: 14:45 on weekdays. Scheduling delays, missing data, or exhausted budgets leave the previous report visible with its original timestamp.</p></section>${sourceRegistry(method)}`}
export function details(report,currency){const c=report.currencies.find(c=>c.currency===currency);return `<div class="eyebrow">${report.demo?'SYNTHETIC EXAMPLE':'CURRENCY BREAKDOWN'}</div><h2>${currency} <span class="muted">${c.score}/100</span></h2><p class="small muted">${esc(c.bias)} · Evidence: ${esc(c.quality)} · Signal agreement: ${esc(c.agreement)}</p><div class="factor"><b>Neutral starting point</b><strong>50</strong></div>${c.factors.map(f=>`<div class="factor"><div><b>${esc(f.label)}</b><p>${esc(f.reason)}</p>${(f.evidenceIds||[]).map(id=>{const e=report.evidence.find(e=>e.id===id);return e?`<p>${safeLink(e.sourceUrl,e.sourceName||'Source unavailable')} · ${esc(e.sourceDate||'Date unavailable')} · ${esc(e.reading)}</p>`:''}).join('')}</div><strong>${sign(f.points)}</strong></div>`).join('')}<div class="factor"><b>Final score (bounded 0–100)</b><strong>${c.score}</strong></div>`}
